import{c as i,Z as t,Q as l,j as g,m as a,o as r}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"离骚","description":"","frontmatter":{"title":"离骚","author":"屈原","dynasty":"战国"},"headers":[],"relativePath":"books/shici/chuci/1.md","filePath":"books/shici/chuci/1.md"}'),e={name:"books/shici/chuci/1.md"};function u(q,o,h,c,p,d){const n=t("PoemAuthor"),s=t("PoemNav");return l(),g("div",null,[o[0]||(o[0]=a('<h1 id="离骚" tabindex="-1">离骚 <a class="header-anchor" href="#离骚" aria-label="Permalink to &quot;离骚&quot;">​</a></h1><p><strong>[战国] <a href="/authors/quyuan.html">屈原</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>帝高阳之苗裔兮，朕皇考曰伯庸。 摄提贞于孟陬兮，惟庚寅吾以降。 皇览揆余初度兮，肇锡余以嘉名： 名余曰正则兮，字余曰灵均。</p><p>纷吾既有此内美兮，又重之以修能。 扈江离与辟芷兮，纫秋兰以为佩。 汩余若将不及兮，恐年岁之不吾与。 朝搴阰之木兰兮，夕揽洲之宿莽。 日月忽其不淹兮，春与秋其代序。 惟草木之零落兮，恐美人之迟暮。 不抚壮而弃秽兮，何不改乎此度？ 乘骐骥以驰骋兮，来吾道夫先路！</p><p>长太息以掩涕兮，哀民生之多艰。 余虽好修姱以鞿羁兮，謇朝谇而夕替。 既替余以蕙纕兮，又申之以揽茝。 亦余心之所善兮，虽九死其犹未悔。 怨灵修之浩荡兮，终不察夫民心。 众女嫉余之蛾眉兮，谣诼谓余以善淫。 固时俗之工巧兮，偭规矩而改错。 背绳墨以追曲兮，竞周容以为度。</p><p>路漫漫其修远兮，吾将上下而求索。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li><strong>高阳</strong>：颛顼帝的称号，传说中五帝之一。</li><li><strong>苗裔</strong>：后代子孙。</li><li><strong>朕</strong>：我。先秦时期不论贵贱皆可自称朕，秦以后才专属皇帝。</li><li><strong>皇考</strong>：对亡父的尊称。</li><li><strong>摄提</strong>：指寅年。古代以太岁在寅曰摄提格。</li><li><strong>孟陬</strong>：正月。夏历正月建寅。</li><li><strong>庚寅</strong>：庚寅日。</li><li><strong>降</strong>：降生。</li><li><strong>揆</strong>：揣度，衡量。</li><li><strong>初度</strong>：初生的时节，指生日。</li><li><strong>肇</strong>：开始。</li><li><strong>锡</strong>：同&quot;赐&quot;，赐予。</li><li><strong>嘉名</strong>：美好的名字。</li><li><strong>纷</strong>：盛多的样子。</li><li><strong>内美</strong>：内在的美德。</li><li><strong>修能</strong>：优秀的才能。能通&quot;耐&quot;，一说指才能。</li><li><strong>扈</strong>：披，楚地方言。</li><li><strong>江离</strong>：香草名，即川芎。</li><li><strong>辟芷</strong>：生长在幽僻处的白芷，香草。</li><li><strong>纫</strong>：连缀，编织。</li><li><strong>秋兰</strong>：香草名。</li><li><strong>汩</strong>：水流迅疾的样子，比喻时光飞逝。</li><li><strong>不吾与</strong>：即&quot;不与吾&quot;，不等待我。</li><li><strong>搴</strong>：拔取。</li><li><strong>阰</strong>：山坡。</li><li><strong>宿莽</strong>：经冬不枯的草，比喻坚贞的操守。</li><li><strong>忽</strong>：迅速。</li><li><strong>淹</strong>：停留。</li><li><strong>代序</strong>：时序更替。</li><li><strong>美人</strong>：比喻君主，一说比喻理想中的贤人。</li><li><strong>迟暮</strong>：年老，比喻时光流逝，功业未建。</li><li><strong>抚</strong>：持，趁着。</li><li><strong>秽</strong>：污秽的行为。</li><li><strong>度</strong>：法度，准则。</li><li><strong>骐骥</strong>：骏马，比喻贤才。</li><li><strong>道</strong>：同&quot;导&quot;，引导。</li><li><strong>太息</strong>：长叹。</li><li><strong>掩涕</strong>：擦拭眼泪。</li><li><strong>修姱</strong>：修洁而美好。</li><li><strong>鞿羁</strong>：马缰绳和马络头，比喻束缚约束。</li><li><strong>謇</strong>：句首语气词，楚地方言。</li><li><strong>谇</strong>：谏诤，劝告。</li><li><strong>替</strong>：废弃，贬黜。</li><li><strong>蕙纕</strong>：用蕙草编成的佩带，比喻美好的品德。</li><li><strong>申</strong>：重复，加上。</li><li><strong>揽茝</strong>：采集白芷，比喻修身洁行。</li><li><strong>灵修</strong>：指楚王。灵修本为神明之称，此处指君主。</li><li><strong>浩荡</strong>：荒唐，没有准则。</li><li><strong>众女</strong>：比喻朝中群小。</li><li><strong>蛾眉</strong>：蚕蛾的触须细长而弯，比喻女子美丽的眉毛，此处比喻美德才能。</li><li><strong>谣诼</strong>：造谣诽谤。</li><li><strong>工巧</strong>：善于取巧。</li><li><strong>偭</strong>：违背。</li><li><strong>绳墨</strong>：木工用以取直的工具，比喻法度。</li><li><strong>周容</strong>：苟合取容，迎合讨好。</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>我是古帝高阳氏的后代，我已故的父亲字伯庸。 正当寅年寅月，恰在庚寅日我降生。 父亲仔细揣度我初生的时节，于是赐给我美好的名字： 给我取名叫&quot;正则&quot;，给我取字叫&quot;灵均&quot;。</p><p>我既有这么多内在的美德，又加上优秀的才能。 披上江离和幽香的白芷，把秋兰连缀起来作为佩饰。 时光像流水般飞逝，我好像追赶不上，唯恐岁月不等待我。 清晨去攀折山坡上的木兰，傍晚去采摘水洲中的宿莽。 日月飞快地运行不停留啊，春天与秋天依次更替。 想到草木的凋零陨落，便担心美人也将衰老。 何不趁着壮年抛弃秽恶的行径，为何不改变这种不好的法度？ 骑着骏马奔驰啊，来吧，我愿为你在前面引路！</p><p>长声叹息而擦拭眼泪啊，为百姓生活的艰难而哀伤。 我虽然爱好修洁而约束自己啊，却早晨进谏而晚上即遭贬黜。 既因为我用蕙草作佩带而贬黜我啊，又因为我采集白芷而加上罪名。 这也是我心中追求的美德啊，即使九死一生我也绝不后悔。 怨恨君心荒唐啊，始终不能体察民心。 众女嫉妒我的美貌啊，造谣诽谤说我善于淫邪。 固然时俗善于取巧啊，违背规矩而任意改变措施。 背弃准绳而追求邪曲啊，争着苟合取容以为法度。</p><p>前面的道路漫长而遥远啊，我将上天下地追求探索。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《离骚》是屈原的代表作，是中国古代最长的抒情诗，全诗三百七十三句，二千四百九十余字。&quot;离骚&quot;二字，司马迁释为&quot;离忧&quot;，班固释为&quot;遭忧&quot;，王逸释为&quot;别愁&quot;。全诗以诗人自述身世、遭遇、心志为中心，抒发了诗人对楚国命运和人民生活的关心，表达了诗人追求理想、坚持正义、不屈不挠的斗争精神。</p><p>诗中运用了大量美人香草的比喻，以&quot;香草&quot;比喻高洁的品质，以&quot;美人&quot;比喻理想中的君主或贤人，以&quot;众女&quot;比喻朝中群小，形成了独特的象征体系。同时，诗人大量运用神话传说，上天入地，驰神运思，想象丰富，意境瑰丽，开创了中国文学史上的&quot;骚体&quot;诗歌形式。</p><p>&quot;路漫漫其修远兮，吾将上下而求索&quot;等名句，表现了诗人对理想的执着追求，成为千古传诵的名句，激励着后世无数仁人志士。《离骚》不仅是中国浪漫主义文学的源头，也是世界文学宝库中的瑰宝，对后世文学产生了深远而持久的影响。</p>',18)),r(n,{name:"屈原",years:"约公元前340年－公元前278年",desc:"名平，字原，战国时期楚国诗人、政治家。中国浪漫主义文学的奠基人，“楚辞”的创立者和代表作家。代表作有《离骚》《九歌》《天问》等。",link:"/authors/quyuan"}),r(s)])}const f=i(e,[["render",u]]);export{m as __pageData,f as default};
